import sys
import os
import json
import re
from datetime import date, timedelta
from decimal import Decimal

def format_date(epd):
    if epd is None:
        return None
    return (date(1970, 1, 1) + timedelta(days=int(epd))).strftime('%Y-%m-%d')

def format_load(dan):
    if dan is None:
        return None
    kn = Decimal(dan) / Decimal('100')
    return str(kn)

def split_tuple(t_str):
    parts = []
    current = []
    in_quotes = False
    for char in t_str:
        if char == "'":
            in_quotes = not in_quotes
            current.append(char)
        elif char == ',' and not in_quotes:
            parts.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if current or t_str.endswith(','):
        parts.append(''.join(current).strip())
    return parts

def extract_inserts(sql_text):
    # Remove single-line comments
    sql_text = re.sub(r'--.*', '', sql_text)
    records = []

    # Find all INSERT INTO statements
    for match in re.finditer(r'INSERT\s+INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);', sql_text, re.DOTALL | re.IGNORECASE):
        cols = [c.strip() for c in match.group(1).split(',')]
        values_str = match.group(2)

        tuples = []
        in_quotes = False
        in_parens = False
        current_tuple = []

        # Extract tuples safely handling strings that might contain parentheses
        for char in values_str:
            if char == "'":
                in_quotes = not in_quotes
                current_tuple.append(char)
            elif char == '(' and not in_quotes:
                in_parens = True
            elif char == ')' and not in_quotes:
                in_parens = False
                tuples.append(''.join(current_tuple))
                current_tuple = []
            elif in_parens:
                current_tuple.append(char)

        for t_str in tuples:
            parts = split_tuple(t_str)
            parsed = {}
            for c, p in zip(cols, parts):
                if p.upper() == 'NULL':
                    parsed[c] = None
                elif p.startswith("'") and p.endswith("'"):
                    parsed[c] = p[1:-1]
                else:
                    parsed[c] = p
            records.append(parsed)

    return records

def get_doc_value(doc_records, cmp_code, col_name, formatter):
    if doc_records is None:
        return None

    values = set()
    for rec in doc_records:
        if rec.get('cmp_code') == cmp_code:
            val = rec.get(col_name)
            if val is not None:
                values.add(formatter(val))

    if len(values) > 1:
        return "CONFLICT"
    elif len(values) == 1:
        return list(values)[0]
    else:
        return None

def get_fact(cmp_code, primary_doc, primary_col, fallback_doc, fallback_col, formatter, docs):
    # Check primary document
    val = get_doc_value(docs.get(primary_doc), cmp_code, primary_col, formatter)
    if val == "CONFLICT":
        return "CONFLICT"
    elif val is not None:
        return [val, primary_doc]

    # Check fallback document if primary has no value
    if fallback_doc:
        val = get_doc_value(docs.get(fallback_doc), cmp_code, fallback_col, formatter)
        if val == "CONFLICT":
            return "CONFLICT"
        elif val is not None:
            return [val, fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    doc_files = {
        "calibration_log": "calibration_log.sql",
        "test_reports": "test_reports.sql",
        "lab_certificates": "lab_certificates.sql",
        "spec_sheets": "spec_sheets.sql",
        "parts": "parts.sql"
    }

    docs = {}
    cmp_codes = set()

    # Read and parse all documents
    for doc_name, file_name in doc_files.items():
        file_path = os.path.join(dir_path, file_name)
        if os.path.exists(file_path):
            with open(file_path, 'r', encoding='utf-8') as f:
                sql_text = f.read()
                records = extract_inserts(sql_text)
                docs[doc_name] = records
                for rec in records:
                    if 'cmp_code' in rec and rec['cmp_code']:
                        cmp_codes.add(rec['cmp_code'])
        else:
            docs[doc_name] = []

    cmp_codes = sorted(list(cmp_codes))
    output = {}

    # Evaluate rules for all components
    for cmp_code in cmp_codes:
        # Rule: ea.calibration_current
        pair_id_cal = f"ea.calibration_current::{cmp_code}"
        output[pair_id_cal] = {
            "calibration date": get_fact(
                cmp_code, 
                "calibration_log", "rig_cal_epd", 
                None, None, 
                format_date, docs
            ),
            "test date": get_fact(
                cmp_code, 
                "test_reports", "inhouse_break_epd", 
                "lab_certificates", "lab_break_epd", 
                format_date, docs
            )
        }

        # Rule: ea.load_with_margin
        pair_id_load = f"ea.load_with_margin::{cmp_code}"
        output[pair_id_load] = {
            "measured load": get_fact(
                cmp_code, 
                "lab_certificates", "lab_break_dan", 
                "test_reports", "inhouse_break_dan", 
                format_load, docs
            ),
            "specified minimum": get_fact(
                cmp_code, 
                "spec_sheets", "floor_force_dan", 
                None, None, 
                format_load, docs
            )
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
