import sys
import os
import json
from decimal import Decimal

def format_decimal(d):
    s = f"{d:f}"
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def parse_edi(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    segments = [seg.replace('\n', '').replace('\r', '') for seg in content.split('~')]

    loops = []
    current_loop = []
    for seg in segments:
        if not seg:
            continue
        parts = seg.split('*')
        if parts[0] == 'LX':
            if current_loop:
                loops.append(current_loop)
            current_loop = [parts]
        elif current_loop:
            current_loop.append(parts)
    if current_loop:
        loops.append(current_loop)

    return loops

def extract_data(loops):
    data = {}
    for loop in loops:
        part_id = None
        loop_data = {}
        for parts in loop:
            if parts[0] == 'LIN' and len(parts) > 3 and parts[1] == '' and parts[2] == 'BP':
                part_id = parts[3]
            elif parts[0] == 'DTP':
                if len(parts) >= 4 and parts[2] == 'D8':
                    qual = parts[1]
                    val = parts[3]
                    if len(val) == 8:
                        date_str = f"{val[:4]}-{val[4:6]}-{val[6:]}"
                        loop_data.setdefault(f"DTP_{qual}", []).append(date_str)
            elif parts[0] == 'MEA':
                if len(parts) >= 5 and parts[1] == 'TE':
                    qual = parts[2]
                    val = parts[3]
                    unit = parts[4]
                    try:
                        d = Decimal(val)
                        if unit == 'NT':
                            d = d / 1000
                        loop_data.setdefault(f"MEA_{qual}", []).append(format_decimal(d))
                    except:
                        pass

        if part_id:
            if part_id not in data:
                data[part_id] = {}
            for k, v_list in loop_data.items():
                if k not in data[part_id]:
                    data[part_id][k] = set()
                for v in v_list:
                    data[part_id][k].add(v)
    return data

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    docs = {
        "calibration_log": extract_data(parse_edi(os.path.join(dir_path, "calibration_log.edi"))),
        "test_reports": extract_data(parse_edi(os.path.join(dir_path, "test_reports.edi"))),
        "lab_certificates": extract_data(parse_edi(os.path.join(dir_path, "lab_certificates.edi"))),
        "spec_sheets": extract_data(parse_edi(os.path.join(dir_path, "spec_sheets.edi"))),
        "parts": extract_data(parse_edi(os.path.join(dir_path, "parts.edi")))
    }

    rules = {
        "ea.calibration_current": {
            "calibration date": [("calibration_log", "DTP_300")],
            "test date": [("test_reports", "DTP_301"), ("lab_certificates", "DTP_302")]
        },
        "ea.load_with_margin": {
            "measured load": [("lab_certificates", "MEA_UFL"), ("test_reports", "MEA_UFH")],
            "specified minimum": [("spec_sheets", "MEA_UFM")]
        }
    }

    all_parts = set()
    for doc_data in docs.values():
        all_parts.update(doc_data.keys())

    sorted_parts = sorted(list(all_parts))

    rules_keys = ["ea.calibration_current", "ea.load_with_margin"]
    pairs = []
    for rule in rules_keys:
        for part in sorted_parts:
            pairs.append(f"{rule}::{part}")

    def resolve_fact(part_id, sources):
        for doc_name, field_name in sources:
            doc_data = docs[doc_name]
            if part_id in doc_data and field_name in doc_data[part_id]:
                values = doc_data[part_id][field_name]
                if len(values) == 1:
                    return [list(values)[0], doc_name]
                elif len(values) > 1:
                    return "CONFLICT"
        return "ABSENT"

    output = {}
    for pair in pairs:
        rule_id, part_id = pair.split("::")
        rule_facts = rules[rule_id]
        pair_result = {}
        for fact_name, sources in rule_facts.items():
            pair_result[fact_name] = resolve_fact(part_id, sources)
        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
