def format_decimal(d):
    s = format(d, 'f')
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def parse_edi(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    segments = content.replace('\n', '').split('~')
    loops = []
    current_loop = []
    for seg in segments:
        seg = seg.strip()
        if not seg:
            continue
        parts = seg.split('*')
        if parts[0] == 'LX':
            if current_loop:
                loops.append(current_loop)
            current_loop = [parts]
        elif current_loop:
            current_loop.append(parts)
    if current_loop:
        loops.append(current_loop)
    return loops

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    parsed_data = {
        'calibration_log.edi': {},
        'test_reports.edi': {},
        'lab_certificates.edi': {},
        'spec_sheets.edi': {}
    }

    entities = set()

    def process_file(filename, doc_name, extract_fn):
        filepath = os.path.join(dir_path, filename)
        if not os.path.exists(filepath):
            return
        loops = parse_edi(filepath)
        for loop in loops:
            part_id = None
            for seg in loop:
                if seg[0] == 'LIN' and len(seg) > 3 and seg[1] == '' and seg[2] == 'BP':
                    part_id = seg[3]
                    entities.add(part_id)
                    break
            if not part_id:
                continue
            if part_id not in parsed_data[doc_name]:
                parsed_data[doc_name][part_id] = {}
            extract_fn(loop, parsed_data[doc_name][part_id])

    def ext_cal(loop, data):
        for seg in loop:
            if seg[0] == 'DTP' and len(seg) > 3 and seg[1] == '300' and seg[2] == 'D8':
                val = f"{seg[3][:4]}-{seg[3][4:6]}-{seg[3][6:8]}"
                data.setdefault('calibration date', set()).add(val)

    def ext_tr(loop, data):
        for seg in loop:
            if seg[0] == 'DTP' and len(seg) > 3 and seg[1] == '301' and seg[2] == 'D8':
                val = f"{seg[3][:4]}-{seg[3][4:6]}-{seg[3][6:8]}"
                data.setdefault('test date', set()).add(val)
            elif seg[0] == 'MEA' and len(seg) > 4 and seg[1] == 'TE' and seg[2] == 'UFH':
                val = Decimal(seg[3])
                if seg[4] == 'NT':
                    val /= Decimal('1000')
                data.setdefault('measured load', set()).add(format_decimal(val))

    def ext_lc(loop, data):
        for seg in loop:
            if seg[0] == 'DTP' and len(seg) > 3 and seg[1] == '302' and seg[2] == 'D8':
                val = f"{seg[3][:4]}-{seg[3][4:6]}-{seg[3][6:8]}"
                data.setdefault('test date', set()).add(val)
            elif seg[0] == 'MEA' and len(seg) > 4 and seg[1] == 'TE' and seg[2] == 'UFL':
                val = Decimal(seg[3])
                if seg[4] == 'NT':
                    val /= Decimal('1000')
                data.setdefault('measured load', set()).add(format_decimal(val))

    def ext_ss(loop, data):
        for seg in loop:
            if seg[0] == 'MEA' and len(seg) > 4 and seg[1] == 'TE' and seg[2] == 'UFM':
                val = Decimal(seg[3])
                if seg[4] == 'NT':
                    val /= Decimal('1000')
                data.setdefault('specified minimum', set()).add(format_decimal(val))

    process_file('calibration_log.edi', 'calibration_log.edi', ext_cal)
    process_file('test_reports.edi', 'test_reports.edi', ext_tr)
    process_file('lab_certificates.edi', 'lab_certificates.edi', ext_lc)
    process_file('spec_sheets.edi', 'spec_sheets.edi', ext_ss)

    parts_path = os.path.join(dir_path, 'parts.edi')
    if os.path.exists(parts_path):
        loops = parse_edi(parts_path)
        for loop in loops:
            for seg in loop:
                if seg[0] == 'LIN' and len(seg) > 3 and seg[1] == '' and seg[2] == 'BP':
                    entities.add(seg[3])
                    break

    def get_fact(entity, fact_name, primary_doc, fallback_doc):
        for doc in [primary_doc, fallback_doc]:
            if not doc:
                continue
            doc_data = parsed_data.get(doc, {})
            entity_data = doc_data.get(entity, {})
            values = entity_data.get(fact_name, set())

            if len(values) == 1:
                return [list(values)[0], doc]
            elif len(values) > 1:
                return "CONFLICT"
        return "ABSENT"

    results = {}

    for entity in sorted(list(entities)):
        pair_id_cal = f"ea.calibration_current::{entity}"
        results[pair_id_cal] = {
            "calibration date": get_fact(entity, "calibration date", "calibration_log.edi", None),
            "test date": get_fact(entity, "test date", "test_reports.edi", "lab_certificates.edi")
        }

        pair_id_load = f"ea.load_with_margin::{entity}"
        results[pair_id_load] = {
            "measured load": get_fact(entity, "measured load", "lab_certificates.edi", "test_reports.edi"),
            "specified minimum": get_fact(entity, "specified minimum", "spec_sheets.edi", None)
        }

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()
