import sys
import os
import json
import re
from collections import defaultdict

def parse_date(s):
    # Matches formats like "March 1st, 2026" or "June 16th, 2026"
    m1 = re.search(r'(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', s, re.IGNORECASE)
    if m1:
        month_str, day_str, year_str = m1.groups()
        return format_date(year_str, month_str, day_str)

    # Matches formats like "11th Jan 2026" or "24th Jul 2026"
    m2 = re.search(r'(\d{1,2})(?:st|nd|rd|th)?\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)(?:,)?\s+(\d{4})', s, re.IGNORECASE)
    if m2:
        day_str, month_str, year_str = m2.groups()
        return format_date(year_str, month_str, day_str)

    return None

def format_date(y, m, d):
    months = {
        'jan': '01', 'january': '01',
        'feb': '02', 'february': '02',
        'mar': '03', 'march': '03',
        'apr': '04', 'april': '04',
        'may': '05',
        'jun': '06', 'june': '06',
        'jul': '07', 'july': '07',
        'aug': '08', 'august': '08',
        'sep': '09', 'september': '09',
        'oct': '10', 'october': '10',
        'nov': '11', 'november': '11',
        'dec': '12', 'december': '12'
    }
    return f"{y}-{months[m.lower()]}-{int(d):02d}"

def parse_load(s):
    m = re.search(r'(\d+(?:\.\d+)?)\s*(?:kN|kilonewtons)', s, re.IGNORECASE)
    if m:
        return m.group(1)
    return None

def get_fact(data, entity, doc1, doc2, field):
    def get_status(doc):
        if not doc: 
            return "ABSENT", None
        if entity not in data[doc]: 
            return "ABSENT", None

        vals = data[doc][entity][field]
        if len(vals) > 1:
            return "CONFLICT", None
        elif len(vals) == 1:
            return "VALUE", list(vals)[0]
        else:
            return "ABSENT", None

    status1, val1 = get_status(doc1)
    if status1 == "VALUE":
        return [val1, doc1]
    elif status1 == "CONFLICT":
        return "CONFLICT"
    else:
        if doc2:
            status2, val2 = get_status(doc2)
            if status2 == "VALUE":
                return [val2, doc2]
            elif status2 == "CONFLICT":
                return "CONFLICT"
            else:
                return "ABSENT"
        else:
            return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    data = {
        'calibration_log': defaultdict(lambda: {'date': set(), 'load': set()}),
        'test_reports': defaultdict(lambda: {'date': set(), 'load': set()}),
        'lab_certificates': defaultdict(lambda: {'date': set(), 'load': set()}),
        'spec_sheets': defaultdict(lambda: {'date': set(), 'load': set()})
    }

    files = [
        ('calibration_log.txt', 'calibration_log'),
        ('test_reports.txt', 'test_reports'),
        ('lab_certificates.txt', 'lab_certificates'),
        ('spec_sheets.txt', 'spec_sheets')
    ]

    all_entities = set()

    # First, discover all entities across all text files to dynamically generate pairs
    for filename in os.listdir(dir_path):
        if not filename.endswith('.txt'):
            continue
        filepath = os.path.join(dir_path, filename)
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
        for match in re.finditer(r'Subject:.*?(P-\d+)', content):
            all_entities.add(match.group(1))

    # Process the specific files needed for the rules
    for filename, doc_name in files:
        filepath = os.path.join(dir_path, filename)
        if not os.path.exists(filepath):
            continue
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        messages = content.split('========================================================================')
        for msg in messages:
            msg = msg.strip()
            if not msg:
                continue

            subj_m = re.search(r'Subject:.*?(P-\d+)', msg)
            if not subj_m:
                continue
            entity = subj_m.group(1)

            parts = msg.split('\n\n', 1)
            if len(parts) < 2:
                body = msg
            else:
                body = parts[1]

            date_val = parse_date(body)
            load_val = parse_load(body)

            if date_val:
                data[doc_name][entity]['date'].add(date_val)
            if load_val:
                data[doc_name][entity]['load'].add(load_val)

    pairs = []
    for entity in sorted(all_entities):
        pairs.append(f"ea.calibration_current::{entity}")
        pairs.append(f"ea.load_with_margin::{entity}")

    output = {}
    for pair in pairs:
        rule, entity = pair.split('::')
        output[pair] = {}
        if rule == 'ea.calibration_current':
            output[pair]['calibration date'] = get_fact(data, entity, 'calibration_log', None, 'date')
            output[pair]['test date'] = get_fact(data, entity, 'test_reports', 'lab_certificates', 'date')
        elif rule == 'ea.load_with_margin':
            output[pair]['measured load'] = get_fact(data, entity, 'lab_certificates', 'test_reports', 'load')
            output[pair]['specified minimum'] = get_fact(data, entity, 'spec_sheets', None, 'load')

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
