import os
import sys
import json
import re
from datetime import datetime
from collections import defaultdict

def parse_date(date_str):
    # Remove ordinal suffixes (st, nd, rd, th)
    date_str = re.sub(r'(?<=\d)(st|nd|rd|th)', '', date_str)
    # Remove commas and normalize spaces
    date_str = date_str.replace(',', '')
    date_str = re.sub(r'\s+', ' ', date_str).strip()

    # Try matching against known formats
    for fmt in ['%B %d %Y', '%b %d %Y', '%d %B %Y', '%d %b %Y']:
        try:
            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    return date_str

def extract_data(directory):
    # data[doc_name][part_id][fact_name] = set_of_values
    data = defaultdict(lambda: defaultdict(lambda: defaultdict(set)))

    regexes = {
        'calibration_log': {
            'calibration date': [
                (r'calibration sticker says (.*?)\.', 'date'),
                (r'last calibrated on (.*?)\.', 'date')
            ]
        },
        'test_reports': {
            'test date': [
                (r'broke it on the frame on (.*?)\.', 'date'),
                (r'In-house break test ran on (.*?)\.', 'date')
            ],
            'measured load': [
                (r'let go at ([\d\.]+) (?:kilonewtons|kN)', 'amount'),
                (r'recorded failure at ([\d\.]+) (?:kilonewtons|kN)', 'amount')
            ]
        },
        'lab_certificates': {
            'test date': [
                (r'lab test happened on (.*?)\.', 'date'),
                (r'accredited lab ran it on (.*?)\.', 'date')
            ],
            'measured load': [
                (r'certifies failure at ([\d\.]+) (?:kilonewtons|kN)', 'amount'),
                (r'failed at ([\d\.]+) (?:kilonewtons|kN)', 'amount')
            ]
        },
        'spec_sheets': {
            'specified minimum': [
                (r'Drawing minimum at failure is ([\d\.]+) (?:kilonewtons|kN)', 'amount'),
                (r'calls for at least ([\d\.]+) (?:kilonewtons|kN) at failure', 'amount')
            ]
        }
    }

    for doc_name, doc_regexes in regexes.items():
        filepath = os.path.join(directory, f"{doc_name}.txt")
        if not os.path.exists(filepath):
            continue

        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        messages = content.split('========================================================================')
        for msg in messages:
            msg = msg.strip()
            if not msg:
                continue

            # Extract part ID
            part_match = re.search(r'(P-\d{5})', msg)
            if not part_match:
                continue
            part_id = part_match.group(1)

            # Extract facts based on regexes
            for fact_name, patterns in doc_regexes.items():
                for pattern, val_type in patterns:
                    match = re.search(pattern, msg)
                    if match:
                        val = match.group(1)
                        if val_type == 'date':
                            val = parse_date(val)
                        else:
                            val = val.strip()
                        data[doc_name][part_id][fact_name].add(val)

    return data

def resolve_fact(part_id, primary_doc, fallback_doc, fact_name, data):
    # Check primary document
    primary_vals = data.get(primary_doc, {}).get(part_id, {}).get(fact_name, set())
    if len(primary_vals) == 1:
        return [list(primary_vals)[0], primary_doc]
    elif len(primary_vals) > 1:
