    # Check fallback document if primary has no value
    if fallback_doc:
        fallback_vals = data.get(fallback_doc, {}).get(part_id, {}).get(fact_name, set())
        if len(fallback_vals) == 1:
            return [list(fallback_vals)[0], fallback_doc]
