import os
import sys
import json
from datetime import datetime

def iso_week_to_date(iso_str):
    return datetime.strptime(iso_str, "%G-W%V-%u").strftime("%Y-%m-%d")

def parse_tsv(filepath):
    lines = []
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip('\n')
            if not line or line.startswith('#'):
                continue
            lines.append(line.split('\t'))

    keys = []
    data = {}
    for parts in lines:
        attr = parts[0]
        values = parts[1:]
        if attr == 'component.key':
            keys = values
        else:
            data[attr] = values

    records_by_entity = {}
    for i, key in enumerate(keys):
        if key not in records_by_entity:
            records_by_entity[key] = {}
        for attr, values in data.items():
            if i < len(values):
                val = values[i]
                if val != '~':
                    if attr not in records_by_entity[key]:
                        records_by_entity[key][attr] = []
                    records_by_entity[key][attr].append(val)
    return records_by_entity

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    db = {}
    all_entities = set()

    for fname in os.listdir(dir_path):
        if fname.endswith('.tsv'):
            doc_name = fname[:-4]
            filepath = os.path.join(dir_path, fname)
            records = parse_tsv(filepath)
            db[doc_name] = records
            all_entities.update(records.keys())

    rules = {
        "ea.calibration_current": {
            "calibration date": {
                "primary": ("calibration_log", "rig.cal.wk"),
                "fallback": None,
                "is_date": True
            },
            "test date": {
                "primary": ("test_reports", "inhouse.break.wk"),
                "fallback": ("lab_certificates", "lab.break.wk"),
                "is_date": True
            }
        },
        "ea.load_with_margin": {
            "measured load": {
                "primary": ("lab_certificates", "lab.break.kn"),
                "fallback": ("test_reports", "inhouse.break.kn"),
                "is_date": False
            },
            "specified minimum": {
                "primary": ("spec_sheets", "floor.force.kn"),
                "fallback": None,
                "is_date": False
            }
        }
    }

    def get_value_from_doc(entity, doc_name, attr):
        if doc_name not in db:
            return "ABSENT", doc_name
        doc_data = db[doc_name]
        if entity not in doc_data:
            return "ABSENT", doc_name
        entity_data = doc_data[entity]
        if attr not in entity_data:
            return "ABSENT", doc_name

        values = set(entity_data[attr])
        if len(values) == 0:
            return "ABSENT", doc_name
        elif len(values) == 1:
            return list(values)[0], doc_name
        else:
            return "CONFLICT", doc_name

    def get_fact(entity, fact_info):
        prim_doc, prim_attr = fact_info["primary"]
        val, doc = get_value_from_doc(entity, prim_doc, prim_attr)

        if val == "CONFLICT":
            return "CONFLICT"
        if val != "ABSENT":
            if fact_info["is_date"]:
                val = iso_week_to_date(val)
            return [val, doc]

        if fact_info["fallback"]:
            fall_doc, fall_attr = fact_info["fallback"]
            val, doc = get_value_from_doc(entity, fall_doc, fall_attr)
            if val == "CONFLICT":
                return "CONFLICT"
            if val != "ABSENT":
                if fact_info["is_date"]:
                    val = iso_week_to_date(val)
                return [val, doc]

        return "ABSENT"

    output = {}
    for rule_name in ["ea.calibration_current", "ea.load_with_margin"]:
        facts = rules[rule_name]
        for entity in sorted(all_entities):
            pair_id = f"{rule_name}::{entity}"
            pair_result = {}
            for fact_name, fact_info in facts.items():
                pair_result[fact_name] = get_fact(entity, fact_info)
            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
