import sys
import os
import json
from decimal import Decimal

def format_date(d):
    if not d:
        return None
    parts = d.split('/')
    if len(parts) == 3:
        return f"{parts[2]}-{parts[0]}-{parts[1]}"
    return None

def format_amount(val, uom):
    if not val:
        return None
    try:
        d = Decimal(val)
        if uom == 'N':
            d = d / Decimal('1000')
        s = f"{d:f}"
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return s
    except:
        return None

def read_dicts(filepath):
    with open(filepath, 'r', encoding='utf-8-sig') as f:
        headers = None
        for line in f:
            if line.startswith('#'):
                continue
            line = line.strip('\n')
            if not line:
                continue
            parts = line.split('|')
            if headers is None:
                headers = parts
            else:
                yield dict(zip(headers, parts))

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    data = {
        "calibration_log": {},
        "lab_certificates": {},
        "parts": {},
