        if os.path.exists(filepath):
            for row in read_dicts(filepath):
                entity = row.get("COMPONENT_CATALOG_KEY")
                if entity:
                    if entity not in data[doc_name]:
                        data[doc_name][entity] = []
                    data[doc_name][entity].append(row)
                    entities.add(entity)

    rules = {
        "ea.calibration_current": {
            "calibration date": [
                ("calibration_log", lambda r: format_date(r.get("LOAD_FRAME_CAL_DAY")))
            ],
            "test date": [
                ("test_reports", lambda r: format_date(r.get("INTERNAL_TRIAL_DAY"))),
                ("lab_certificates", lambda r: format_date(r.get("ACCREDITED_TRIAL_DAY")))
            ]
        },
        "ea.load_with_margin": {
            "measured load": [
                ("lab_certificates", lambda r: format_amount(r.get("ACCREDITED_ULTIMATE_FORCE"), r.get("ACCREDITED_ULTIMATE_FORCE_UOM"))),
                ("test_reports", lambda r: format_amount(r.get("INTERNAL_ULTIMATE_FORCE"), r.get("INTERNAL_ULTIMATE_FORCE_UOM")))
            ],
            "specified minimum": [
                ("spec_sheets", lambda r: format_amount(r.get("REQUIRED_ULTIMATE_FORCE"), r.get("REQUIRED_ULTIMATE_FORCE_UOM")))
            ]
        }
    }

    pairs = []
    for rule_id in rules.keys():
        for entity in sorted(entities):
            pairs.append(f"{rule_id}::{entity}")

    results = {}

    for pair in pairs:
        rule_id, entity = pair.split("::")
        rule_facts = rules[rule_id]

        pair_result = {}
        for fact_name, sources in rule_facts.items():
            fact_val = "ABSENT"
            for doc_name, extract_func in sources:
                rows = data[doc_name].get(entity, [])
                values = set()
                for row in rows:
                    val = extract_func(row)
                    if val is not None:
                        values.add(val)

                if len(values) == 1:
                    fact_val = [list(values)[0], doc_name]
                    break
                elif len(values) > 1:
                    fact_val = "CONFLICT"
                    break

            pair_result[fact_name] = fact_val

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
