import os
import re
import sys
import json

def clean_html(raw_html):
    cleanr = re.compile('<.*?>')
    cleantext = re.sub(cleanr, '', raw_html)
    return cleantext.strip()

def parse_date(s):
    m = re.search(r'([A-Z][a-z]+\.?) (\d{1,2}), (\d{4})', s)
    if m:
        month_str = m.group(1)[:3]
        months = {
            "Jan": "01", "Feb": "02", "Mar": "03", "Apr": "04",
            "May": "05", "Jun": "06", "Jul": "07", "Aug": "08",
            "Sep": "09", "Oct": "10", "Nov": "11", "Dec": "12"
        }
        month = months[month_str]
        day = m.group(2).zfill(2)
        year = m.group(3)
        return f"{year}-{month}-{day}"
    return None

def parse_amount(s):
    m = re.search(r'(\d+(?:\.\d+)?)', s)
    if m:
        return m.group(1)
    return None

def process_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    doc_data = {}
    sheet_pattern = re.compile(r'<article class="sheet".*?</article>', re.DOTALL)
    item_code_pattern = re.compile(r'<th>Item code</th>\s*<td[^>]*>.*?(P-\d+).*?</td>', re.DOTALL)
    field_pattern = re.compile(r'<th>(.*?)</th>\s*<td([^>]*)>(.*?)</td>', re.DOTALL)

    for sheet in sheet_pattern.findall(content):
        ic_match = item_code_pattern.search(sheet)
        if not ic_match:
            continue
        item_code = ic_match.group(1)

        if item_code not in doc_data:
            doc_data[item_code] = {}

        for f_match in field_pattern.finditer(sheet):
            field_name = clean_html(f_match.group(1)).strip()
            if field_name == "Item code":
                continue

            td_attrs = f_match.group(2)
            td_content = f_match.group(3)

            if 'class="void"' in td_attrs:
                continue

            val_str = clean_html(td_content).strip()

            if field_name in ["Frame last calibrated", "Break test performed", "Laboratory test performed"]:
                val = parse_date(val_str)
            elif field_name in ["Load at failure (in-house)", "Load at failure (lab certified)", "Drawing minimum at failure"]:
                val = parse_amount(val_str)
            else:
                val = val_str

            if val is not None:
                if field_name not in doc_data[item_code]:
                    doc_data[item_code][field_name] = set()
                doc_data[item_code][field_name].add(val)

    return doc_data

def resolve_fact(item_code, sources, all_docs):
    for doc_name, field_name in sources:
        if doc_name in all_docs:
            doc_data = all_docs[doc_name]
            if item_code in doc_data:
                if field_name in doc_data[item_code]:
                    values = doc_data[item_code][field_name]
