def parse_date(date_str):
    m = re.search(r'(Jan|Feb|March|April|May|June|July|Aug|Sept|Oct|Nov|Dec)\.?\s+(\d+),\s+(\d{4})', date_str)
    if not m:
        return None
    month_str, day_str, year_str = m.groups()
    months = {
        'Jan': '01', 'Feb': '02', 'March': '03', 'April': '04',
        'May': '05', 'June': '06', 'July': '07', 'Aug': '08',
        'Sept': '09', 'Oct': '10', 'Nov': '11', 'Dec': '12'
    }
    return f"{year_str}-{months[month_str]}-{int(day_str):02d}"

def parse_amount(amount_str):
    m = re.search(r'([\d\.]+)\s*kN', amount_str)
    if m:
        return m.group(1)
    return None

def parse_html(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    articles = re.findall(r'<article class="sheet".*?</article>', content, re.DOTALL)

    parsed_data = {}
    for article in articles:
        item_match = re.search(r'<th>Item code</th>\s*(<td[^>]*>.*?</td>)', article, re.DOTALL)
        if not item_match:
            continue
        td_full = item_match.group(1)
        inner = re.search(r'<td[^>]*>(.*?)</td>', td_full, re.DOTALL).group(1)
        item_code = re.sub(r'<[^>]+>', '', inner).strip()

        if item_code not in parsed_data:
            parsed_data[item_code] = {}

        rows = re.findall(r'<tr>\s*<th>(.*?)</th>\s*(<td[^>]*>.*?</td>)\s*</tr>', article, re.DOTALL)
        for th, td_full in rows:
            th = th.strip()
            if 'Item code' in th:
                continue

            if re.search(r'class=["\']void["\']', td_full):
                val = None
            else:
                inner = re.search(r'<td[^>]*>(.*?)</td>', td_full, re.DOTALL).group(1)
                val = re.sub(r'<[^>]+>', '', inner).strip()

            if th not in parsed_data[item_code]:
                parsed_data[item_code][th] = []
            parsed_data[item_code][th].append(val)

    return parsed_data

def get_fact(item_code, primary_doc, primary_field, fallback_doc, fallback_field, data, is_date=False):
