            valid_vals = [v for v in vals if v is not None]
            if valid_vals:
                primary_vals = valid_vals

    if primary_vals:
        parsed_vals = set()
        for v in primary_vals:
            pv = parse_date(v) if is_date else parse_amount(v)
            if pv is not None:
                parsed_vals.add(pv)
        if len(parsed_vals) > 1:
            return "CONFLICT"
        elif len(parsed_vals) == 1:
            return [list(parsed_vals)[0], primary_doc]
        else:
            return "ABSENT"

    if fallback_doc:
        fallback_vals = []
