import sys
import os
import re
import json
from datetime import date, timedelta
from decimal import Decimal

def epd_to_date(epd_str):
    if epd_str is None:
        return None
    epd = int(epd_str)
    return (date(1970, 1, 1) + timedelta(days=epd)).strftime('%Y-%m-%d')

def dan_to_kn(dan_str):
    if dan_str is None:
        return None
    val = Decimal(dan_str) / Decimal('100')
    return str(val)

def parse_tuples(values_str):
    tuples = []
    in_string = False
    current_tuple = []
    current_val = []
    in_tuple = False

    for char in values_str:
        if char == "'" and not in_string:
            in_string = True
            current_val.append(char)
        elif char == "'" and in_string:
            in_string = False
            current_val.append(char)
        elif char == '(' and not in_string:
            in_tuple = True
            current_tuple = []
            current_val = []
        elif char == ')' and not in_string:
            if in_tuple:
                current_tuple.append(''.join(current_val).strip())
                tuples.append(current_tuple)
                in_tuple = False
                current_val = []
        elif char == ',' and not in_string:
            if in_tuple:
                current_tuple.append(''.join(current_val).strip())
                current_val = []
        else:
            if in_tuple:
                current_val.append(char)
    return tuples

def parse_sql(file_content):
    records = []
    inserts = re.finditer(r'INSERT\s+INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);', file_content, re.DOTALL | re.IGNORECASE)
    for insert in inserts:
        cols = [c.strip() for c in insert.group(1).split(',')]
        values_str = insert.group(2)
        tuples = parse_tuples(values_str)
        for t in tuples:
            record = {}
            for k, v in zip(cols, t):
                if v.upper() == 'NULL':
                    record[k] = None
                elif v.startswith("'") and v.endswith("'"):
                    record[k] = v[1:-1]
                else:
                    record[k] = v
            records.append(record)
    return records

def get_fact_from_doc(doc_data, cmp_code, field_name, transform=None):
    if cmp_code not in doc_data:
        return "ABSENT"
    records = doc_data[cmp_code]
    values = set()
    for r in records:
        val = r.get(field_name)
        if val is not None:
            if transform:
                val = transform(val)
            values.add(val)
    if not values:
        return "ABSENT"
    if len(values) > 1:
        return "CONFLICT"
    return list(values)[0]

def get_fact(data, cmp_code, primary_doc, primary_field, fallback_doc, fallback_field, transform):
    val = get_fact_from_doc(data[primary_doc], cmp_code, primary_field, transform)
    if val == "ABSENT" and fallback_doc:
        val_fallback = get_fact_from_doc(data[fallback_doc], cmp_code, fallback_field, transform)
        if val_fallback not in ("ABSENT", "CONFLICT"):
            return [val_fallback, fallback_doc]
        elif val_fallback == "CONFLICT":
            return "CONFLICT"
        else:
            return "ABSENT"
    elif val not in ("ABSENT", "CONFLICT"):
        return [val, primary_doc]
    else:
        return val

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    directory = sys.argv[1]

    files = {
        'calibration_log': 'calibration_log.sql',
        'lab_certificates': 'lab_certificates.sql',
        'spec_sheets': 'spec_sheets.sql',
        'test_reports': 'test_reports.sql',
        'parts': 'parts.sql'
    }

    data = {k: {} for k in files}
    all_cmp_codes = set()

    for k, filename in files.items():
        path = os.path.join(directory, filename)
        if not os.path.exists(path):
            continue
        with open(path, 'r', encoding='utf-8-sig') as f:
            content = f.read()
        records = parse_sql(content)
        for r in records:
            cmp_code = r.get('cmp_code')
            if cmp_code:
                data[k].setdefault(cmp_code, []).append(r)
                all_cmp_codes.add(cmp_code)

    all_cmp_codes = sorted(list(all_cmp_codes))

    RULES = {
        "ea.calibration_current": {
            "calibration date": {
                "primary_doc": "calibration_log",
                "primary_field": "rig_cal_epd",
                "fallback_doc": None,
                "fallback_field": None,
                "transform": epd_to_date
            },
            "test date": {
                "primary_doc": "test_reports",
                "primary_field": "inhouse_break_epd",
                "fallback_doc": "lab_certificates",
                "fallback_field": "lab_break_epd",
                "transform": epd_to_date
            }
        },
        "ea.load_with_margin": {
            "measured load": {
                "primary_doc": "lab_certificates",
                "primary_field": "lab_break_dan",
                "fallback_doc": "test_reports",
                "fallback_field": "inhouse_break_dan",
                "transform": dan_to_kn
            },
            "specified minimum": {
                "primary_doc": "spec_sheets",
                "primary_field": "floor_force_dan",
                "fallback_doc": None,
                "fallback_field": None,
                "transform": dan_to_kn
            }
        }
    }

    output = {}
    for rule_name, facts in RULES.items():
        for cmp_code in all_cmp_codes:
            pair_id = f"{rule_name}::{cmp_code}"
            pair_result = {}
            for fact_name, config in facts.items():
                pair_result[fact_name] = get_fact(
                    data,
                    cmp_code,
                    config["primary_doc"],
                    config["primary_field"],
                    config["fallback_doc"],
                    config["fallback_field"],
                    config["transform"]
                )
            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
