from decimal import Decimal

def parse_load(val, unit):
    d = Decimal(val)
    if unit == 'NT':
        d = d / Decimal('1000')
    d = d.normalize()
    return format(d, 'f')

def parse_edi(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    segments = content.split('~')

    data = {}
    current_loop = {}
    current_part = None

    for seg in segments:
        seg = seg.strip()
        if not seg:
            continue
        parts = seg.split('*')
        if parts[0] == 'LX':
            if current_part is not None:
                if current_part not in data:
                    data[current_part] = []
                data[current_part].append(current_loop)
            current_loop = {}
            current_part = None
        elif parts[0] == 'LIN' and len(parts) >= 4 and parts[1] == '':
            if parts[2] == 'BP':
                current_part = parts[3]
        else:
            if parts[0] not in current_loop:
                current_loop[parts[0]] = []
            current_loop[parts[0]].append(parts[1:])

    if current_part is not None:
        if current_part not in data:
            data[current_part] = []
        data[current_part].append(current_loop)

    return data

def get_fact_values(doc_data, part_id, extract_fn):
    if part_id not in doc_data:
        return []
    values = []
    for loop in doc_data[part_id]:
        val = extract_fn(loop)
        if val is not None:
            values.append(val)
    return values

def ext_calib_date(loop):
