import os
import sys
import json
from decimal import Decimal

def parse_edi(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    segments = [seg.strip() for seg in content.split('~') if seg.strip()]

    loops = []
    current_loop = []
    for seg in segments:
        if seg.startswith('LX*'):
            if current_loop:
                loops.append(current_loop)
            current_loop = [seg]
        elif current_loop is not None:
            current_loop.append(seg)
    if current_loop:
        loops.append(current_loop)

    return loops

def extract_data(directory):
    docs = {
        'calibration_log': {},
        'test_reports': {},
        'lab_certificates': {},
        'spec_sheets': {}
    }

    def process_file(filename, doc_name, extractors):
        path = os.path.join(directory, filename)
        if not os.path.exists(path):
            return
        loops = parse_edi(path)
        for loop in loops:
            part_id = None
            for seg in loop:
                parts = seg.split('*')
                if len(parts) >= 4 and parts[0] == 'LIN' and parts[1] == '' and parts[2] == 'BP':
                    part_id = parts[3].strip()
                    break
            if not part_id:
                continue

            for seg in loop:
                parts = seg.split('*')
                for field, extractor in extractors.items():
                    val = extractor(parts)
                    if val is not None:
                        docs[doc_name].setdefault(part_id, {}).setdefault(field, set()).add(val)

    def ext_cal_date(parts):
        if len(parts) >= 4 and parts[0] == 'DTP' and parts[1] == '300' and parts[2] == 'D8':
            d = parts[3].strip()
            if len(d) == 8:
                return f"{d[:4]}-{d[4:6]}-{d[6:]}"
        return None

    def ext_test_date_301(parts):
        if len(parts) >= 4 and parts[0] == 'DTP' and parts[1] == '301' and parts[2] == 'D8':
            d = parts[3].strip()
            if len(d) == 8:
                return f"{d[:4]}-{d[4:6]}-{d[6:]}"
        return None

    def ext_test_date_302(parts):
        if len(parts) >= 4 and parts[0] == 'DTP' and parts[1] == '302' and parts[2] == 'D8':
            d = parts[3].strip()
            if len(d) == 8:
                return f"{d[:4]}-{d[4:6]}-{d[6:]}"
        return None

    def ext_load(parts, qual):
        if len(parts) >= 5 and parts[0] == 'MEA' and parts[1] == 'TE' and parts[2] == qual:
            val = parts[3].strip()
            unit = parts[4].strip()
            try:
                v = Decimal(val)
                if unit == 'NT':
                    v /= Decimal('1000')
                v = v.normalize()
                return '{:f}'.format(v)
            except:
                pass
        return None

    process_file('calibration_log.edi', 'calibration_log', {
        'calibration date': ext_cal_date
    })

    process_file('test_reports.edi', 'test_reports', {
        'test date': ext_test_date_301,
        'measured load': lambda p: ext_load(p, 'UFH')
    })

    process_file('lab_certificates.edi', 'lab_certificates', {
        'test date': ext_test_date_302,
        'measured load': lambda p: ext_load(p, 'UFL')
    })

    process_file('spec_sheets.edi', 'spec_sheets', {
        'specified minimum': lambda p: ext_load(p, 'UFM')
    })

    return docs

def resolve_fact(docs, part_id, sources):
    for doc_name, field_name in sources:
        part_data = docs[doc_name].get(part_id, {})
        if field_name in part_data:
            values = part_data[field_name]
            if len(values) == 1:
                return [list(values)[0], doc_name]
            elif len(values) > 1:
                return "CONFLICT"
    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    directory = sys.argv[1]

    docs = extract_data(directory)

    all_part_ids = set()
    for filename in os.listdir(directory):
        if filename.endswith('.edi'):
            path = os.path.join(directory, filename)
            if not os.path.isfile(path):
                continue
            loops = parse_edi(path)
            for loop in loops:
                for seg in loop:
                    parts = seg.split('*')
                    if len(parts) >= 4 and parts[0] == 'LIN' and parts[1] == '' and parts[2] == 'BP':
                        all_part_ids.add(parts[3].strip())
                        break

    rules = {
        'ea.calibration_current': {
            'calibration date': [('calibration_log', 'calibration date')],
            'test date': [('test_reports', 'test date'), ('lab_certificates', 'test date')]
        },
        'ea.load_with_margin': {
            'measured load': [('lab_certificates', 'measured load'), ('test_reports', 'measured load')],
            'specified minimum': [('spec_sheets', 'specified minimum')]
        }
    }

    pairs = []
    for p in sorted(all_part_ids):
        pairs.append(f"ea.calibration_current::{p}")
    for p in sorted(all_part_ids):
        pairs.append(f"ea.load_with_margin::{p}")

    output = {}
    for pair in pairs:
        rule_id, part_id = pair.split('::')
        if rule_id not in rules:
            continue
        rule_facts = rules[rule_id]

        pair_result = {}
        for fact_name, sources in rule_facts.items():
            pair_result[fact_name] = resolve_fact(docs, part_id, sources)

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
