import sys
import os
import re
import json
from collections import defaultdict
from datetime import datetime

def parse_date(s):
    s = re.sub(r'(st|nd|rd|th)', '', s)
    s = s.replace(',', '')
    s = re.sub(r'\s+', ' ', s.strip())
    formats = ['%B %d %Y', '%b %d %Y', '%d %B %Y', '%d %b %Y']
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    return None

def extract_data(directory):
    data = defaultdict(lambda: defaultdict(lambda: defaultdict(set)))

    # calibration_log
    path = os.path.join(directory, 'calibration_log.txt')
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            for email in f.read().split('========================================================================'):
                m_ent = re.search(r'P-\d{5}', email)
                if not m_ent: continue
                ent = m_ent.group(0)

                m_date = re.search(r'(?:calibrated on|sticker says)\s+([A-Za-z0-9,\s]+)\.', email)
                if m_date:
                    d = parse_date(m_date.group(1))
                    if d: data['calibration_log'][ent]['calibration date'].add(d)
                elif re.search(r"can't find.*calibration", email, re.IGNORECASE):
                    data['calibration_log'][ent]['calibration date'].add(None)

    # test_reports
    path = os.path.join(directory, 'test_reports.txt')
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            for email in f.read().split('========================================================================'):
                m_ent = re.search(r'P-\d{5}', email)
                if not m_ent: continue
                ent = m_ent.group(0)

                m_date = re.search(r'(?:ran on|frame on)\s+([A-Za-z0-9,\s]+)\.', email)
                if m_date:
                    d = parse_date(m_date.group(1))
                    if d: data['test_reports'][ent]['test date'].add(d)

                m_load = re.search(r'(?:let go at|failure at)\s+(\d+)\s*(?:kN|kilonewtons)', email, re.IGNORECASE)
                if m_load:
                    data['test_reports'][ent]['measured load'].add(m_load.group(1))

    # lab_certificates
    path = os.path.join(directory, 'lab_certificates.txt')
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            for email in f.read().split('========================================================================'):
                m_ent = re.search(r'P-\d{5}', email)
                if not m_ent: continue
                ent = m_ent.group(0)

                m_date = re.search(r'(?:ran it on|happened on)\s+([A-Za-z0-9,\s]+)\.', email)
                if m_date:
                    d = parse_date(m_date.group(1))
                    if d: data['lab_certificates'][ent]['test date'].add(d)

                m_load = re.search(r'(?:failure at|failed at)\s+(\d+)\s*(?:kN|kilonewtons)', email, re.IGNORECASE)
                if m_load:
                    data['lab_certificates'][ent]['measured load'].add(m_load.group(1))
                elif re.search(r"leaves the failure load empty", email, re.IGNORECASE):
                    data['lab_certificates'][ent]['measured load'].add(None)

    # spec_sheets
    path = os.path.join(directory, 'spec_sheets.txt')
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            for email in f.read().split('========================================================================'):
                m_ent = re.search(r'P-\d{5}', email)
                if not m_ent: continue
                ent = m_ent.group(0)

                m_load = re.search(r'(?:minimum at failure is|at least)\s+(\d+)\s*(?:kN|kilonewtons)', email, re.IGNORECASE)
                if m_load:
                    data['spec_sheets'][ent]['specified minimum'].add(m_load.group(1))
                elif re.search(r"gives no minimum failure load", email, re.IGNORECASE):
                    data['spec_sheets'][ent]['specified minimum'].add(None)

    return data

def main():
    if len(sys.argv) < 2:
        return
    directory = sys.argv[1]

    data = extract_data(directory)

    rules = {
        "ea.calibration_current": {
            "calibration date": ("calibration_log", None),
            "test date": ("test_reports", "lab_certificates")
        },
        "ea.load_with_margin": {
            "measured load": ("lab_certificates", "test_reports"),
            "specified minimum": ("spec_sheets", None)
        }
    }

    pairs = [
        f"ea.calibration_current::P-{40800+i}" for i in range(1, 17)
    ] + [
        f"ea.load_with_margin::P-{40800+i}" for i in range(1, 17)
    ]

    def get_fact(entity, primary_doc, fallback_doc, fact_name):
        def evaluate_doc(doc):
            if doc not in data or entity not in data[doc] or fact_name not in data[doc][entity]:
                return "ABSENT"

            values = data[doc][entity][fact_name]
            if len(values) == 0:
                return "ABSENT"
            elif len(values) > 1:
                return "CONFLICT"
            else:
                val = list(values)[0]
                if val is None:
                    return "ABSENT"
                else:
                    return [val, doc]

        res = evaluate_doc(primary_doc)
        if res == "ABSENT" and fallback_doc:
            res = evaluate_doc(fallback_doc)
        return res

    output = {}
    for pair in pairs:
        rule, entity = pair.split("::")
        output[pair] = {}
        for fact_name, (primary_doc, fallback_doc) in rules[rule].items():
            output[pair][fact_name] = get_fact(entity, primary_doc, fallback_doc, fact_name)

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
