import sys
import os
import json
import re
from datetime import datetime

def parse_date(date_str):
    if re.match(r'^\d{4}-\d{2}-\d{2}$', date_str):
        return date_str
    # Remove ordinal suffixes only if they follow a digit
    date_str = re.sub(r'(?<=\d)(st|nd|rd|th)\b', '', date_str, flags=re.IGNORECASE)
    date_str = date_str.replace(',', '')
    # Normalize common month abbreviations if needed
    date_str = re.sub(r'\bSept\b', 'Sep', date_str, flags=re.IGNORECASE)
    date_str = re.sub(r'\s+', ' ', date_str).strip()

    for fmt in ('%B %d %Y', '%b %d %Y', '%d %B %Y', '%d %b %Y'):
        try:
            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    return None

def extract_date(text, pattern):
    m = re.search(pattern, text, re.IGNORECASE)
    if m:
        return parse_date(m.group(1))
    return None

def extract_amount(text, pattern):
    m = re.search(pattern, text, re.IGNORECASE)
    if m:
        return m.group(1).replace(',', '')
    return None

def get_fact(part_id, docs, primary_doc, fallback_doc, extract_fn, primary_pattern, fallback_pattern=None):
    primary_values = set()
    for email in docs.get(primary_doc, []):
        if email['part_id'] == part_id:
            val = extract_fn(email['body'], primary_pattern)
            if val is not None:
                primary_values.add(val)

    if len(primary_values) == 1:
        return [list(primary_values)[0], primary_doc]
    elif len(primary_values) > 1:
        return "CONFLICT"

    if fallback_doc:
        fallback_values = set()
        for email in docs.get(fallback_doc, []):
            if email['part_id'] == part_id:
                val = extract_fn(email['body'], fallback_pattern)
                if val is not None:
                    fallback_values.add(val)

        if len(fallback_values) == 1:
            return [list(fallback_values)[0], fallback_doc]
        elif len(fallback_values) > 1:
            return "CONFLICT"

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    files = [
        'calibration_log.txt',
        'lab_certificates.txt',
        'parts.txt',
        'spec_sheets.txt',
        'test_reports.txt'
    ]

    docs = {}
    part_ids = set()

    for filename in files:
        filepath = os.path.join(dir_path, filename)
        if not os.path.exists(filepath):
            docs[filename] = []
            continue

        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        emails = []
        parts = content.split('========================================================================')
        for part in parts:
            part = part.strip()
            if not part or part.startswith('MAILBOX EXPORT'):
                continue

            m_subj = re.search(r'Subject: .*?(P-\d{5})', part)
            if m_subj:
                pid = m_subj.group(1)
                emails.append({
                    'part_id': pid,
                    'body': part
                })
                part_ids.add(pid)
        docs[filename] = emails

    # Regex patterns for extraction
    date_regex = r'([a-z]+\s+\d{1,2}(?:st|nd|rd|th)?,?\s+\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+[a-z]+,?\s+\d{4}|\d{4}-\d{2}-\d{2})'

    pat_calib_date = r'(?:calibrated on|sticker says)\s+' + date_regex
    pat_test_date_tr = r'(?:broke it on the frame on|break test ran on)\s+' + date_regex
    pat_test_date_lc = r'(?:lab test happened on|lab ran it on)\s+' + date_regex

    pat_meas_load_lc = r'(?:failed at|failure at)\s+([\d,]+(?:\.\d+)?)\s*(?:kN|kilonewtons)'
    pat_meas_load_tr = r'(?:failure at|let go at)\s+([\d,]+(?:\.\d+)?)\s*(?:kN|kilonewtons)'
    pat_spec_min = r'(?:minimum at failure is|at least)\s+([\d,]+(?:\.\d+)?)\s*(?:kN|kilonewtons)'

    results = {}

    for part_id in sorted(list(part_ids)):
        # Rule: ea.calibration_current
        calib_date = get_fact(part_id, docs, 'calibration_log.txt', None, extract_date, pat_calib_date)
        test_date = get_fact(part_id, docs, 'test_reports.txt', 'lab_certificates.txt', extract_date, pat_test_date_tr, pat_test_date_lc)

        results[f"ea.calibration_current::{part_id}"] = {
            "calibration date": calib_date,
            "test date": test_date
        }

        # Rule: ea.load_with_margin
        meas_load = get_fact(part_id, docs, 'lab_certificates.txt', 'test_reports.txt', extract_amount, pat_meas_load_lc, pat_meas_load_tr)
        spec_min = get_fact(part_id, docs, 'spec_sheets.txt', None, extract_amount, pat_spec_min)

        results[f"ea.load_with_margin::{part_id}"] = {
            "measured load": meas_load,
            "specified minimum": spec_min
        }

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
