import sys
import os
import json
from datetime import datetime

def parse_crosstab(filepath):
    records = []
    if not os.path.exists(filepath):
        return records
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    attributes = []
    data = []
    for line in lines:
        if line.startswith('#') or not line.strip():
            continue
        parts = line.strip('\n').split('\t')
        if parts[0] == 'attribute':
            continue
        attributes.append(parts[0])
        data.append(parts[1:])

    if not data:
        return []

    num_records = len(data[0])
    for i in range(num_records):
        record = {}
        for j, attr in enumerate(attributes):
            if i < len(data[j]):
                val = data[j][i].strip()
                if val != '~':
                    record[attr] = val
        records.append(record)
    return records

def convert_date(val):
    if not val:
        return val
    try:
        dt = datetime.strptime(val, "%G-W%V-%u")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        return val

def get_fact(entity, docs_data, primary_doc, primary_field, fallback_doc=None, fallback_field=None, is_date=False):
    # Check primary document
    primary_records = docs_data.get(primary_doc, [])
    primary_vals = set()
    for rec in primary_records:
        if rec.get('component.key') == entity and primary_field in rec:
            primary_vals.add(rec[primary_field])

    if len(primary_vals) == 1:
        val = primary_vals.pop()
        if is_date:
            val = convert_date(val)
        return [val, primary_doc]
    elif len(primary_vals) > 1:
        return "CONFLICT"

    # Check fallback document if primary has no value
    if fallback_doc and fallback_field:
        fallback_records = docs_data.get(fallback_doc, [])
        fallback_vals = set()
        for rec in fallback_records:
            if rec.get('component.key') == entity and fallback_field in rec:
                fallback_vals.add(rec[fallback_field])

        if len(fallback_vals) == 1:
            val = fallback_vals.pop()
            if is_date:
                val = convert_date(val)
            return [val, fallback_doc]
        elif len(fallback_vals) > 1:
            return "CONFLICT"

    return "ABSENT"

def main():
