import sys
import os
import json
from datetime import datetime

def parse_tsv(filepath):
    data = {}
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\r\n')
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) > 0:
                data[parts[0]] = parts[1:]
    return data

def get_entity_values(parsed_data, entity_id, attribute_name):
    if 'component.key' not in parsed_data or attribute_name not in parsed_data:
        return []
    keys = parsed_data['component.key']
    vals = parsed_data[attribute_name]

    extracted = []
    for k, v in zip(keys, vals):
        if k == entity_id and v != '~':
            extracted.append(v)
    return extracted

def format_date(iso_week_date):
    try:
        dt = datetime.strptime(iso_week_date, "%G-W%V-%u")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        return iso_week_date

def resolve_fact(entity_id, primary_doc, primary_attr, fallback_doc, fallback_attr, docs, is_date=False):
    # Check primary document
    if primary_doc in docs:
        primary_vals = get_entity_values(docs[primary_doc], entity_id, primary_attr)
        unique_primary = set(primary_vals)
        if len(unique_primary) > 1:
            return "CONFLICT"
        elif len(unique_primary) == 1:
            val = unique_primary.pop()
            if is_date:
                val = format_date(val)
            return [val, primary_doc]

    # Check fallback document if primary has no value
    if fallback_doc and fallback_doc in docs:
        fallback_vals = get_entity_values(docs[fallback_doc], entity_id, fallback_attr)
        unique_fallback = set(fallback_vals)
        if len(unique_fallback) > 1:
            return "CONFLICT"
        elif len(unique_fallback) == 1:
            val = unique_fallback.pop()
            if is_date:
                val = format_date(val)
            return [val, fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    # Load all documents
    docs = {}
    for doc_name in ["calibration_log", "lab_certificates", "parts", "spec_sheets", "test_reports"]:
        filepath = os.path.join(dir_path, f"{doc_name}.tsv")
        if os.path.exists(filepath):
            docs[doc_name] = parse_tsv(filepath)
        else:
            docs[doc_name] = {}

    # Identify all unique entities across all documents
    entities = set()
    for doc_data in docs.values():
        if 'component.key' in doc_data:
            entities.update(doc_data['component.key'])
    entities = sorted(list(entities))

    results = {}

    for entity in entities:
        # Rule: ea.calibration_current
        pair_id_cal = f"ea.calibration_current::{entity}"
        cal_date = resolve_fact(entity, "calibration_log", "rig.cal.wk", None, None, docs, is_date=True)
        test_date = resolve_fact(entity, "test_reports", "inhouse.break.wk", "lab_certificates", "lab.break.wk", docs, is_date=True)

        results[pair_id_cal] = {
            "calibration date": cal_date,
            "test date": test_date
        }

        # Rule: ea.load_with_margin
        pair_id_load = f"ea.load_with_margin::{entity}"
        measured_load = resolve_fact(entity, "lab_certificates", "lab.break.kn", "test_reports", "inhouse.break.kn", docs, is_date=False)
        specified_min = resolve_fact(entity, "spec_sheets", "floor.force.kn", None, None, docs, is_date=False)

        results[pair_id_load] = {
            "measured load": measured_load,
            "specified minimum": specified_min
        }

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
