import sys
import os
import json
from decimal import Decimal

def parse_date(d):
    if not d:
        return None
    m, day, y = d.split('/')
    return f"{y}-{m}-{day}"

def parse_force(val, uom):
    if not val:
        return None
    d = Decimal(val)
    if uom == 'N':
        d /= 1000
    s = format(d, 'f')
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def read_file(filepath, key_idx, val_func):
    res = {}
    if not os.path.exists(filepath):
        return res
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.read().splitlines()

    data_lines = [line for line in lines if line and not line.startswith('#')]
    if not data_lines:
        return res

    for line in data_lines[1:]:
        cols = line.split('|')
        if len(cols) <= key_idx:
            continue
        key = cols[key_idx]
        try:
            val = val_func(cols)
        except Exception:
            val = None
        if val is None:
            continue
        if key not in res:
            res[key] = val
        elif res[key] != val:
            res[key] = "CONFLICT"
    return res

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    cal_log_path = os.path.join(dir_path, 'calibration_log.txt')
    lab_cert_path = os.path.join(dir_path, 'lab_certificates.txt')
    test_rep_path = os.path.join(dir_path, 'test_reports.txt')
    spec_sheets_path = os.path.join(dir_path, 'spec_sheets.txt')

    cal_log_data = read_file(cal_log_path, 1, lambda c: parse_date(c[4]))

    test_rep_date_data = read_file(test_rep_path, 1, lambda c: parse_date(c[4]))
    lab_cert_date_data = read_file(lab_cert_path, 1, lambda c: parse_date(c[4]))

    lab_cert_load_data = read_file(lab_cert_path, 1, lambda c: parse_force(c[6], c[7]))
    test_rep_load_data = read_file(test_rep_path, 1, lambda c: parse_force(c[6], c[7]))

    spec_min_data = read_file(spec_sheets_path, 1, lambda c: parse_force(c[4], c[5]))

    def get_keys(filepath):
        keys = set()
        if not os.path.exists(filepath): return keys
        with open(filepath, 'r', encoding='utf-8') as f:
            lines = f.read().splitlines()
        data_lines = [line for line in lines if line and not line.startswith('#')]
        for line in data_lines[1:]:
            cols = line.split('|')
            if len(cols) > 1:
                keys.add(cols[1])
        return keys

    entities = set()
    for fname in ['calibration_log.txt', 'lab_certificates.txt', 'parts.txt', 'spec_sheets.txt', 'test_reports.txt']:
        entities.update(get_keys(os.path.join(dir_path, fname)))

    entities = sorted(list(entities))

    results = {}

    for ent in entities:
        # ea.calibration_current
        pair_id = f"ea.calibration_current::{ent}"
        facts = {}

        val = cal_log_data.get(ent)
        if val is None:
            facts["calibration date"] = "ABSENT"
        elif val == "CONFLICT":
            facts["calibration date"] = "CONFLICT"
        else:
            facts["calibration date"] = [val, "calibration_log.txt"]

        val1 = test_rep_date_data.get(ent)
        if val1 == "CONFLICT":
            facts["test date"] = "CONFLICT"
        elif val1 is not None:
            facts["test date"] = [val1, "test_reports.txt"]
        else:
            val2 = lab_cert_date_data.get(ent)
            if val2 == "CONFLICT":
                facts["test date"] = "CONFLICT"
            elif val2 is not None:
                facts["test date"] = [val2, "lab_certificates.txt"]
            else:
                facts["test date"] = "ABSENT"

        results[pair_id] = facts

        # ea.load_with_margin
        pair_id2 = f"ea.load_with_margin::{ent}"
        facts2 = {}

        val1 = lab_cert_load_data.get(ent)
        if val1 == "CONFLICT":
            facts2["measured load"] = "CONFLICT"
        elif val1 is not None:
            facts2["measured load"] = [val1, "lab_certificates.txt"]
        else:
            val2 = test_rep_load_data.get(ent)
            if val2 == "CONFLICT":
                facts2["measured load"] = "CONFLICT"
            elif val2 is not None:
                facts2["measured load"] = [val2, "test_reports.txt"]
            else:
                facts2["measured load"] = "ABSENT"

        val = spec_min_data.get(ent)
        if val is None:
            facts2["specified minimum"] = "ABSENT"
        elif val == "CONFLICT":
            facts2["specified minimum"] = "CONFLICT"
        else:
            facts2["specified minimum"] = [val, "spec_sheets.txt"]

        results[pair_id2] = facts2

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()
